+#>
+[CmdletBinding()]
+param(
+    [ValidateSet('Read','Git','Search','Files','Hash','Gh')][string]$Mode = 'Read',
+    [string]$Path,
+    [int]$Start = 1,
+    [int]$Count = 200,
