+        if ($Path -match '(?i)(AGENTS-README-FIRST\.yaml|cred-legion2|\.ssh/|\.creds/)') { throw 'Sensitive path: use the redacted bootstrap reader.' }
+        $lines = [IO.File]::ReadAllLines((Resolve-Path -LiteralPath $Path).ProviderPath)
