+    }
+    'Git' {
+        if ($argumentList[0] -notin @('status','log','diff','show','merge-base','rev-parse','cat-file','ls-tree','ls-files','check-attr','merge-tree','reflog')) { throw 'Not a read-only git inspection verb.' }
