+    'Hash' { Get-FileHash -LiteralPath $Path -Algorithm SHA256 | Select-Object Path, Hash | ConvertTo-Json -Compress }
+    'Gh' {
+        if ($argumentList[0] -ne 'pr' -or $argumentList[1] -ne 'view') { throw 'Only gh pr view is permitted.' }
+        & gh @argumentList
+        $exitCode = $LASTEXITCODE
+    }
+}
+$text = $result | Out-String -Width 500
