+$manifest = Get-Content -LiteralPath $manifestPath -Raw | ConvertFrom-Json
+$issues = [Collections.Generic.List[object]]::new()
+$rows = [Collections.Generic.List[object]]::new()
+$testIndex = [Collections.Generic.List[object]]::new()
+function Get-CommittedBlobHash {
+    <# .SYNOPSIS Hashes a git blob's exact stdout bytes without a text encoding conversion. #>
+    param([string]$RepositoryPath)
+    $info = [Diagnostics.ProcessStartInfo]::new()
+    $info.FileName = 'git'
+    $info.WorkingDirectory = $root
+    $info.UseShellExecute = $false
+    $info.RedirectStandardOutput = $true
+    $info.RedirectStandardError = $true
+    $info.ArgumentList.Add('cat-file')
+    $info.ArgumentList.Add('blob')
+    $info.ArgumentList.Add("${reviewHead}:$RepositoryPath")
+    $process = [Diagnostics.Process]::Start($info)
+    $errorTask = $process.StandardError.ReadToEndAsync()
+    $hash = [Security.Cryptography.SHA256]::HashData($process.StandardOutput.BaseStream)
+    $process.WaitForExit()
+    if ($process.ExitCode -ne 0) { throw $errorTask.GetAwaiter().GetResult() }
+    return [Convert]::ToHexString($hash)
+}
+foreach ($file in $manifest.files) {
+    $path = Join-Path $root $file.path
+    $hash = (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash
+    $blobHash = Get-CommittedBlobHash -RepositoryPath $file.path
+    $originalHash = if (Test-Path -LiteralPath $file.sourcePath -PathType Leaf) { (Get-FileHash -LiteralPath $file.sourcePath -Algorithm SHA256).Hash } else { $null }
+    $row = [ordered]@{RunId=$file.runId;Host=$file.host;Kind=$file.kind;Path=$file.path;Head=$file.head;Hash=$hash;ExpectedHash=$file.sha256;BlobHash=$blobHash;OriginalHash=$originalHash;OriginalPresent=($null -ne $originalHash);Bytes=(Get-Item -LiteralPath $path).Length;Counters=$null;Results=0;UniqueNames=0;Classes=@();Computers=@();AllResultsPassed=$null}
+    if ($hash -ne $file.sha256 -or $blobHash -ne $file.sha256 -or ($originalHash -and $originalHash -ne $file.sha256)) { $issues.Add(@{Path=$file.path;Issue='Hash mismatch'}) }
+    if ($file.head -ne $codeHead) { $issues.Add(@{Path=$file.path;Issue='Wrong code head in manifest'}) }
+    if ($row.Bytes -ne $file.bytes) { $issues.Add(@{Path=$file.path;Issue='Byte count mismatch'}) }
+    if ($path.EndsWith('.trx')) {
+        $xml = [xml][IO.File]::ReadAllText($path)
+        $counters = $xml.TestRun.ResultSummary.Counters
+        $counterValues = [ordered]@{}
+        foreach ($attribute in $counters.Attributes) { $counterValues[$attribute.Name] = [int]$attribute.Value }
+        $row.Counters = $counterValues
+        $results = @($xml.TestRun.Results.UnitTestResult)
+        $row.Results = $results.Count
+        $row.UniqueNames = @($results.testName | Sort-Object -Unique).Count
+        $row.Classes = @($xml.TestRun.TestDefinitions.UnitTest.TestMethod.className | Sort-Object -Unique)
+        $row.Computers = @($results.computerName | Sort-Object -Unique)
+        $row.AllResultsPassed = @($results | Where-Object outcome -ne 'Passed').Count -eq 0
+        foreach ($name in @('total','executed','passed','failed','notExecuted')) {
+            if ([int]$counters.$name -ne [int]$file.$name) { $issues.Add(@{Path=$file.path;Issue="Manifest counter differs: $name"}) }
+        }
+        if ($results.Count -ne [int]$counters.executed -or -not $row.AllResultsPassed -or [int]$counters.total -ne [int]$counters.passed) { $issues.Add(@{Path=$file.path;Issue='Results/count/pass mismatch'}) }
+        foreach ($result in $results) { $testIndex.Add([ordered]@{RunId=$file.runId;Project=[IO.Path]::GetFileNameWithoutExtension($path);Name=[string]$result.testName;Outcome=[string]$result.outcome;TestId=[string]$result.testId;ExecutionId=[string]$result.executionId;Start=[string]$result.startTime;End=[string]$result.endTime}) }
+    }
+    $rows.Add($row)
+}
+$manifestHash = (Get-FileHash -LiteralPath $manifestPath -Algorithm SHA256).Hash
+$manifestBlobHash = Get-CommittedBlobHash -RepositoryPath 'docs/receipts/hv/unitgreen-r9-trx-878c366f/manifest.json'
+$expectedManifestHash = '56204BC1CFC7471CC502F761F2228D80466DA3D4635493E3FA9D47C6D3C42978'
+if ($manifestHash -ne $expectedManifestHash -or $manifestBlobHash -ne $expectedManifestHash) { $issues.Add(@{Path='manifest.json';Issue='Manifest digest mismatch'}) }
+$runs = @($rows | Group-Object RunId | ForEach-Object {
+    $trx = @($_.Group | Where-Object { $null -ne $_.Counters })
+    [ordered]@{RunId=$_.Name;TrxFiles=$trx.Count;Total=($trx.Counters.total | Measure-Object -Sum).Sum;Passed=($trx.Counters.passed | Measure-Object -Sum).Sum;Failed=($trx.Counters.failed | Measure-Object -Sum).Sum;NotExecuted=($trx.Counters.notExecuted | Measure-Object -Sum).Sum;ActualResults=($trx.Results | Measure-Object -Sum).Sum}
+})
+$audit = [ordered]@{TimestampLocal=(Get-Date).ToString('s');TimestampUtc=(Get-Date).ToUniversalTime().ToString('o');Head=$reviewHead;CodeHead=$codeHead;ManifestHash=$manifestHash;ManifestBlobHash=$manifestBlobHash;Files=$rows.Count;TrxFiles=@($rows | Where-Object { $null -ne $_.Counters }).Count;Bytes=($rows.Bytes | Measure-Object -Sum).Sum;Issues=$issues.ToArray();Runs=$runs;Details=$rows.ToArray()}
+[IO.File]::WriteAllText((Join-Path $receiptRoot 'hv-ug-r9-trx-audit.json'), ($audit | ConvertTo-Json -Depth 30))
+[IO.File]::WriteAllText((Join-Path $receiptRoot 'hv-ug-r9-trx-index.json'), ($testIndex.ToArray() | ConvertTo-Json -Depth 8))
+$audit.Remove('Details')
+$audit | ConvertTo-Json -Depth 20
